const D = { scale: 1, energy: .6, hue: 50, speed: 1, density: .5, plump: .5, x: .5, y: .72, seed: 0, pose: 'auto', style: 'gloss', act: 'pond' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const TAU = 6.28318530718;
const u = Math.min(width, height);
const s = u * 0.0019 * P.scale;

let bt = K.beat * P.speed;
const sb = ((bt % 1) + 1) % 1;
if (S.lastBeat == null || bt < S.lastBeat) S.lastBeat = bt;
S.lastBeat = bt;
const am = .82 + .22 * Math.sin(K.t * .29 + fr(6) * 6);
const loco = (.72 + .5 * K.intensity) * am;
const eAmp = (.35 + .65 * P.energy) * (.6 + .55 * K.intensity) * am;
const kick = Math.min(1, K.pulse * (.5 + .5 * K.intensity) + A.bass * .8);
S.rms = (S.rms || 0) * .85 + (A.rms || 0) * .15;
S.tre = (S.tre || 0) * .8 + (A.treble || 0) * .2;

const ACTS = {
  pond:  ['float','waddle','float','headbang','waddle','float','headbang','waddle'],
  strut: ['waddle','headbang','waddle','float','headbang','waddle','float','headbang'],
  chill: ['float','float','waddle','float','float','waddle','float','headbang'] };
let pose = P.pose;
if (pose === 'auto') pose = (ACTS[P.act] || ACTS.pond)[((K.section % 8) + 8) % 8];

const slow1 = Math.sin(K.t * .5 + fr(2) * 6);
const slow2 = Math.sin(K.t * .34 + fr(4) * 6);

let dy = 0, sway = 0, tilt = 0, headNod = 0, headRot = 0, tailA = 0, wingA = 0, footStep = 0, onWater = 0;
const quackBase = Math.min(1, K.pulse * .35 + A.bass * .9);
let quack = quackBase * .5;

if (pose === 'float') {
  onWater = 1;
  dy = Math.sin(bt * Math.PI / 2) * 13 * loco;
  tilt = Math.sin(bt * Math.PI / 2 + 1) * .05 * loco + slow2 * .02;
  headRot = Math.sin(K.t * .6) * .12;
  headNod = Math.sin(bt * Math.PI) * 3 * eAmp;
  tailA = Math.sin(bt * Math.PI / 2) * .12;
  wingA = Math.sin(bt * Math.PI) * .12 * eAmp;
  quack = quackBase * (fr(Math.floor(K.t * .7) + 5) < .18 ? .8 : .12);
} else if (pose === 'waddle') {
  const side = (((Math.floor(bt) % 2) + 2) % 2 === 0) ? 1 : -1;
  const w = Math.sin(sb * Math.PI);
  sway = side * 16 * w * loco;
  tilt = side * .13 * w * loco;
  dy = -Math.abs(Math.sin(bt * Math.PI)) * 5 * loco;
  footStep = side;
  headNod = Math.abs(Math.sin(bt * Math.PI)) * 6 * eAmp;
  headRot = side * .08 * w;
  tailA = -side * .18 * w;
  wingA = .1 + Math.sin(bt * Math.PI) * .14 * eAmp;
  quack = Math.max(quack, fr(Math.floor(bt) + 12) < .22 ? kick * .7 : quack);
} else {                                                     // headbang
  const nod = Math.pow(kick, 1.2);
  headNod = nod * 30 * (.5 + eAmp) + 3;
  headRot = nod * .34;
  dy = -kick * 4 - Math.abs(Math.sin(bt * Math.PI)) * 3 * loco;
  tailA = kick * .5;
  wingA = .2 + kick * .5 * eAmp;
  sway = Math.sin(bt * Math.PI) * 6 * loco;
  tilt = Math.sin(bt * TAU) * .04 * eAmp;
  quack = Math.max(quack, kick * .6);
}

// universal slow drift
dy += slow1 * 3;
sway += slow2 * 4.5;
tilt += Math.sin(K.t * .19 + fr(8) * 6) * .026;

// ---- style ----
const styles = ['gloss', 'chrome', 'noir', 'contour'];
const st = styles.indexOf(P.style) >= 0 ? P.style : 'gloss';
const contour = st === 'contour';
const H = ((P.hue % 360) + 360) % 360;
const plump = P.plump;
const bw = .86 + plump * .4;

// glossy / chrome / noir / contour blob
function blob(cx, cy, w, h, hh, sat, br) {
  push(); translate(cx, cy);
  if (contour) { noFill(); stroke(hh, 62, 38, 92); strokeWeight(2 * s); ellipse(0, 0, w, h); pop(); return; }
  noStroke();
  if (st === 'noir') {
    fill(hh, sat * .38, br * .26); ellipse(0, 0, w, h);
    fill(hh, sat * .28, Math.min(100, br * .52), 65); ellipse(-w * .16, -h * .2, w * .66, h * .66);
    pop(); return;
  }
  if (st === 'chrome') {
    for (let b = 0; b < 5; b++) { const f = b / 5; fill((hh + f * 120 + K.t * 9 + kick * 40) % 360, 42 + 42 * f, 58 + 34 * (1 - f), 78); ellipse(-w * .05 * f, -h * .09 * f, w * (1 - f * .17), h * (1 - f * .17)); }
    fill(0, 0, 100, 88); ellipse(-w * .2, -h * .26, w * .17, h * .15);
    pop(); return;
  }
  // gloss (default picture-book): stacked translucent shading + specular
  fill(hh, Math.min(100, sat + 16), br * .6); ellipse(0, 0, w, h);
  fill((hh + 4) % 360, sat, br * .9); ellipse(-w * .04, -h * .05, w * .92, h * .92);
  fill(hh, sat * .74, Math.min(100, br * 1.02 + 6)); ellipse(-w * .13, -h * .15, w * .64, h * .64);
  fill(0, 0, 100, 72); ellipse(-w * .22, -h * .27, w * .2, h * .15);
  pop();
}

const ax = P.x * width + sway * s;
const ay = P.y * height;
const pump = 1 + S.rms * .32 * P.energy;

// water ripples (float/waddle-on-pond feel) or ground shadow
if (onWater && !contour) {
  noStroke();
  for (let i = 0; i < 3; i++) {
    const ph = ((K.t * .5 + i * .34) % 1);
    const rr = (30 + ph * 150) * s;
    fill(195, 45, 90, (1 - ph) * (st === 'noir' ? 18 : 30));
    noFill(); stroke(195, 40, 92, (1 - ph) * (st === 'noir' ? 22 : 40)); strokeWeight(2 * s);
    ellipse(P.x * width, ay + 70 * s, rr * 1.8, rr * .6);
  }
  noStroke();
} else if (!contour) {
  noStroke(); fill(0, 0, 0, 24);
  ellipse(P.x * width, ay + 120 * s, Math.max(14, 150 * bw - Math.abs(sway) * .3) * s, 16 * s);
}

push();
translate(ax, ay + dy * s);
rotate(tilt);
scale(pump, pump);

// feet (orange) — hidden on water, stepping on land
if (!onWater) {
  const fH = 30, fS = 92, fB = 98;
  const lift = footStep;
  push(); translate(-24 * s, (112 - (lift < 0 ? Math.abs(Math.sin(sb * Math.PI)) * 13 : 0)) * s);
  if (contour) { noFill(); stroke(fH, 60, 50, 92); strokeWeight(2 * s); } else { noStroke(); fill(fH, fS, fB); }
  triangle(-16 * s, 8 * s, 16 * s, 8 * s, 0, -6 * s); pop();
  push(); translate(24 * s, (112 - (lift > 0 ? Math.abs(Math.sin(sb * Math.PI)) * 13 : 0)) * s);
  if (contour) { noFill(); stroke(fH, 60, 50, 92); strokeWeight(2 * s); } else { noStroke(); fill(fH, fS, fB); }
  triangle(-16 * s, 8 * s, 16 * s, 8 * s, 0, -6 * s); pop();
} else {
  // waterline mask: draw a bed-tone band over lower body so duck sits IN water
}

// tail (back, up-left) — flips with tailA
push(); translate(-74 * bw * s, 30 * s); rotate(-.5 - tailA);
blob(0, 0, 46 * s, 30 * s, H, 78, 92);
pop();

// body mass
blob(8 * s, 40 * s, 168 * bw * s, 138 * s, H, 82, 96);

// wing on flank
push(); translate(2 * s, 44 * s); rotate(-.15 - wingA);
if (contour) { noFill(); stroke(H, 60, 38, 92); strokeWeight(2 * s); ellipse(0, 0, 90 * bw * s, 60 * s); }
else { noStroke(); fill(H, Math.min(100, 88), 76, 60); ellipse(0, 0, 90 * bw * s, 60 * s); fill(H, 70, 90, 40); ellipse(-6 * s, -6 * s, 66 * bw * s, 42 * s); }
pop();

// waterline: hide lower body in the pond
if (onWater && !contour) {
  noStroke();
  fill(200, 34, st === 'noir' ? 20 : 70, st === 'noir' ? 92 : 78);
  const wl = 78 * s;
  rect(-140 * s, wl, 300 * s, 130 * s);
  fill(195, 48, 96, st === 'noir' ? 30 : 46);
  ellipse(0, wl, 220 * bw * s, 26 * s);
}

// head (big, forward-up) with nod + rotation
push();
translate(-4 * s, -66 * s + headNod * s);
rotate(headRot);
blob(0, 0, 124 * s, 116 * s, H, 82, 98);

// bill (orange) — upper + lower, opens with quack
const qo = quack * 12 * s;
const bH = 30, bS = 94, bB = 98;
push(); translate(58 * s, 4 * s);
if (contour) {
  noFill(); stroke(bH, 62, 52, 92); strokeWeight(2 * s);
  beginShape(); vertex(-6 * s, -8 * s - qo * .3); vertex(42 * s, -4 * s - qo * .3); vertex(46 * s, 4 * s); vertex(-4 * s, 8 * s); endShape(CLOSE);
} else {
  noStroke();
  fill(bH, bS, bB);
  quad(-8 * s, -9 * s - qo, 44 * s, -6 * s - qo, 48 * s, 1 * s - qo, -6 * s, 1 * s - qo);       // upper bill
  fill(bH, Math.min(100, bS + 4), bB * .82);
  quad(-8 * s, 3 * s + qo, 48 * s, 1 * s + qo, 44 * s, 8 * s + qo, -6 * s, 9 * s + qo);          // lower bill
  if (qo > 2 * s) { fill(2, 82, 34); quad(-6 * s, 1 * s - qo * .3, 44 * s, -2 * s - qo * .3, 44 * s, 2 * s + qo * .3, -6 * s, 3 * s + qo * .3); }
}
pop();

// eye
const blink = ((K.t * .3 + fr(9)) % 1) < .04;
if (contour) {
  noFill(); stroke(H, 60, 38, 92); strokeWeight(2 * s); ellipse(26 * s, -18 * s, 12 * s, 12 * s);
} else if (blink) {
  stroke(0, 0, st === 'noir' ? 4 : 8); strokeWeight(2.4 * s); noFill();
  line(20 * s, -18 * s, 32 * s, -18 * s); noStroke();
} else {
  noStroke(); fill(0, 0, 100); ellipse(26 * s, -18 * s, 15 * s, 16 * s);
  fill(0, 0, st === 'noir' ? 6 : 8); ellipse(27 * s, -18 * s, 9 * s, 10 * s);
  fill(0, 0, 100, 92); ellipse(25 * s, -21 * s, 4 * s, 4 * s);
}
pop();

// noir key light over whole figure
if (st === 'noir') {
  const g = drawingContext.createRadialGradient(-30 * s, -80 * s, 5 * s, -30 * s, -80 * s, 190 * s);
  g.addColorStop(0, 'rgba(255,248,228,0.5)'); g.addColorStop(1, 'rgba(255,248,228,0)');
  drawingContext.save(); drawingContext.globalCompositeOperation = 'screen'; drawingContext.fillStyle = g;
  drawingContext.fillRect(-150 * s, -170 * s, 320 * s, 340 * s); drawingContext.restore();
}

pop();

// ambient motes / bubbles (density)
if (P.density > 0.02 && !contour) {
  const n = Math.round(P.density * 20);
  noStroke();
  for (let i = 0; i < n; i++) {
    const ph = (K.t * (.1 + fr(i + 50) * .16) + fr(i + 70)) % 1;
    const fx = (fr(i + 90) - .5) * u * 1.0 + P.x * width;
    const fy = P.y * height + 60 * s - ph * u * .5;
    const tw = .5 + .5 * Math.sin(K.t * 2.4 + i);
    fill(onWater ? 195 : 50, onWater ? 30 : 10, 100, (12 + 20 * tw) * (.4 + .6 * P.density));
    ellipse(fx, fy, (2.5 + 2.6 * tw + S.tre * 5) * s, (2.5 + 2.6 * tw) * s);
  }
}
